    step6Label: "\u0420\u0435\u0433\u0443\u043B\u044F\u0442\u043E\u0440\u043D\u0456 \u0437\u043C\u0456\u043D\u0438",
    step1Title: "\u0417\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u0443\u0439\u0442\u0435\u0441\u044C \u0442\u0430 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0439\u0442\u0435 \u043E\u0431\u043B\u0456\u043A\u043E\u0432\u0438\u0439 \u0437\u0430\u043F\u0438\u0441",
    step1Body: "\u0421\u0442\u0432\u043E\u0440\u0435\u043D\u043D\u044F \u043E\u0431\u043B\u0456\u043A\u043E\u0432\u043E\u0433\u043E \u0437\u0430\u043F\u0438\u0441\u0443 DSCVR \u0437\u0430\u0439\u043C\u0430\u0454 \u043C\u0435\u043D\u0448\u0435 2 \u0445\u0432\u0438\u043B\u0438\u043D. \u0412\u0432\u0435\u0434\u0456\u0442\u044C \u0435\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u0443 \u043F\u043E\u0448\u0442\u0443 \u0442\u0430 \u043F\u0430\u0440\u043E\u043B\u044C \u2014 \u0456 \u0432\u0441\u0435. \u041A\u0440\u0435\u0434\u0438\u0442\u043D\u0430 \u043A\u0430\u0440\u0442\u043A\u0430 \u043D\u0435 \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0430. \u0412\u0430\u0448 \u0431\u0435\u0437\u043A\u043E\u0448\u0442\u043E\u0432\u043D\u0438\u0439 \u043E\u0431\u043B\u0456\u043A\u043E\u0432\u0438\u0439 \u0437\u0430\u043F\u0438\u0441 \u0434\u0430\u0454 \u043F\u043E\u0441\u0442\u0456\u0439\u043D\u0438\u0439 \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u043E \u043E\u0433\u043B\u044F\u0434\u0443 \u0432\u043E\u0440\u0456\u0442 \u0442\u0430 \u0440\u0435\u0433\u0443\u043B\u044F\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0445\u0430\u0431\u0443.",
    step2Title: "\u041E\u043F\u0438\u0448\u0456\u0442\u044C \u0432\u0430\u0448\u0443 \u043D\u0435\u0440\u0443\u0445\u043E\u043C\u0456\u0441\u0442\u044C",
    step2Body: "\u0420\u043E\u0437\u043A\u0430\u0436\u0456\u0442\u044C DSCVR \u043F\u0440\u043E \u0432\u0430\u0448\u0443 \u043D\u0435\u0440\u0443\u0445\u043E\u043C\u0456\u0441\u0442\u044C \u2014 \u0442\u0438\u043F, \u0440\u0430\u0439\u043E\u043D, \u043A\u0456\u043B\u044C\u043A\u0456\u0441\u0442\u044C \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u0443, OTA-\u043B\u0456\u0441\u0442\u0438\u043D\u0433\u0438 \u0442\u0430 \u043F\u043E\u0442\u043E\u0447\u043D\u0438\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u0434\u043E\u0437\u0432\u043E\u043B\u0456\u0432. \u0426\u0435 \u0437\u0430\u0439\u043C\u0430\u0454 \u0431\u043B\u0438\u0437\u044C\u043A\u043E 5 \u0445\u0432\u0438\u043B\u0438\u043D. DSCVR \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454 \u0446\u044E \u0456\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0456\u044E \u0434\u043B\u044F \u0432\u0438\u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0432\u0430\u0448\u0438\u0445 \u0437\u043E\u0431\u043E\u0432\u2019\u044F\u0437\u0430\u043D\u044C.",
    step3Title: "\u041F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u044C\u0442\u0435 \u0432\u0430\u0448\u0456 \u0432\u043E\u0440\u043E\u0442\u0430 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u043E\u0441\u0442\u0456",
    step3Body: "DSCVR \u0432\u0456\u0434\u043E\u0431\u0440\u0430\u0436\u0430\u0454 \u0432\u0435\u0441\u044C \u0448\u043B\u044F\u0445 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u043E\u0441\u0442\u0456 \u0443 8 \u043F\u043E\u0441\u043B\u0456\u0434\u043E\u0432\u043D\u0438\u0445 \u0432\u043E\u0440\u0456\u0442 \u2014 \u0432\u0456\u0434 \u0440\u0435\u0454\u0441\u0442\u0440\u0430\u0446\u0456\u0457 \u043F\u0456\u0434\u043F\u0440\u0438\u0454\u043C\u0441\u0442\u0432\u0430 \u0434\u043E \u0432\u0435\u0440\u0438\u0444\u0456\u043A\u0430\u0446\u0456\u0457 OTA-\u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0438. \u0411\u0435\u0437\u043A\u043E\u0448\u0442\u043E\u0432\u043D\u0438\u0439 \u043E\u0431\u043B\u0456\u043A\u043E\u0432\u0438\u0439 \u0437\u0430\u043F\u0438\u0441 \u043F\u043E\u043A\u0430\u0437\u0443\u0454 \u043F\u043E\u0432\u043D\u0443 \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0443 \u0432\u043E\u0440\u0456\u0442.",
    step4Title: "\u041F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u043D\u0430 Pro",
    step4Body: "\u041A\u043E\u043B\u0438 \u0432\u0438 \u0433\u043E\u0442\u043E\u0432\u0456 \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0432\u0456\u0434 \u043E\u0433\u043B\u044F\u0434\u0443 \u0434\u043E \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0433\u043E \u0443\u043F\u0440\u0430\u0432\u043B\u0456\u043D\u043D\u044F \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u0456\u0441\u0442\u044E, \u043E\u043D\u043E\u0432\u0456\u0442\u044C \u0434\u043E Pro. \u0411\u0435\u0437 \u043F\u0440\u0438\u0432\u2019\u044F\u0437\u043A\u0438: \u0432\u0438 \u043F\u043B\u0430\u0442\u0438\u0442\u0435 \u0449\u043E\u043C\u0456\u0441\u044F\u0446\u044F \u0456 \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u043A\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0431\u0443\u0434\u044C-\u043A\u043E\u043B\u0438.",
    step5Title: "\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0439\u0442\u0435 \u0441\u043F\u043E\u0432\u0456\u0449\u0435\u043D\u043D\u044F \u0442\u0430 \u0441\u0445\u043E\u0432\u0438\u0449\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0456\u0432",
    step5Body: "\u041F\u0456\u0441\u043B\u044F \u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F \u0432\u0438\u0442\u0440\u0430\u0442\u044C\u0442\u0435 10 \u0445\u0432\u0438\u043B\u0438\u043D \u043D\u0430 \u0434\u0432\u0430 \u043D\u0430\u0439\u0432\u0430\u0436\u043B\u0438\u0432\u0456\u0448\u0456 \u043A\u0440\u043E\u043A\u0438: \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043C\u0430\u0440\u0448\u0440\u0443\u0442\u0438\u0437\u0430\u0446\u0456\u0457 \u0441\u043F\u043E\u0432\u0456\u0449\u0435\u043D\u044C \u0442\u0430 \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043D\u044F \u043D\u0430\u044F\u0432\u043D\u0438\u0445 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0456\u0432.",
    step6Title: "\u0411\u0443\u0434\u044C\u0442\u0435 \u043F\u043E\u043F\u0435\u0440\u0435\u0434\u0443 \u2014 \u0440\u0435\u0433\u0443\u043B\u044F\u0442\u043E\u0440\u043D\u0430 \u0440\u043E\u0437\u0432\u0456\u0434\u043A\u0430",
    step6Body: "\u0406\u043D\u0434\u043E\u043D\u0435\u0437\u0456\u0439\u0441\u044C\u043A\u0456 \u0440\u0435\u0433\u0443\u043B\u044F\u0446\u0456\u0457 \u0447\u0430\u0441\u0442\u043E \u0437\u043C\u0456\u043D\u044E\u044E\u0442\u044C\u0441\u044F. DSCVR \u043C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u0442\u044C \u0440\u0435\u0433\u0443\u043B\u044F\u0442\u043E\u0440\u043D\u0456 \u0434\u0436\u0435\u0440\u0435\u043B\u0430 \u0442\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E \u043E\u043D\u043E\u0432\u043B\u044E\u0454 \u0432\u0430\u0448 \u043A\u0430\u043B\u0435\u043D\u0434\u0430\u0440 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u043E\u0441\u0442\u0456.",
