    finalSub: "\u0411\u0435\u0437\u043A\u043E\u0448\u0442\u043E\u0432\u043D\u043E. \u0411\u0435\u0437 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438. \u0417\u0430\u0439\u043C\u0430\u0454 60 \u0441\u0435\u043A\u0443\u043D\u0434.",
