    footerDisclaimer: "\u0426\u044F \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0430 \u043D\u0430\u0434\u0430\u0454 \u043E\u043F\u0435\u0440\u0430\u0446\u0456\u0439\u043D\u0456 \u043F\u043E\u0441\u0456\u0431\u043D\u0438\u043A\u0438 \u0442\u0430 \u0432\u0456\u0434\u0441\u0442\u0435\u0436\u0435\u043D\u043D\u044F \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0456\u0432. \u0426\u0435 \u043D\u0435 \u044E\u0440\u0438\u0434\u0438\u0447\u043D\u0430, \u043F\u043E\u0434\u0430\u0442\u043A\u043E\u0432\u0430, \u0456\u043C\u043C\u0456\u0433\u0440\u0430\u0446\u0456\u0439\u043D\u0430 \u0430\u0431\u043E \u0440\u0435\u0433\u0443\u043B\u044F\u0442\u043E\u0440\u043D\u0430 \u043F\u043E\u0440\u0430\u0434\u0430.",
